#!/usr/bin/env python3
"""patch_species_by_name.py -- a species can be asked for by NAME.

Zoo 0.37.0 -> 0.38.0. First piece of the Layer 3 placement chain.

THE PROBLEM, WHICH IS OLDER THAN THE DRESSING WORK.

There was exactly one way to request a species: describe it in a prompt and
hope `intent._find_species` keyword-matched the right one. That is the correct
interface for a person and the wrong one for a program, and it had already
failed twice with nothing to notice:

  1. `wallCorner` and `wallEnd` cannot be requested AT ALL.
     `intent.parse("wall corner").species` is None -- their keyword sets never
     covered their own names. Both species are in the library, both pass
     `test_genome`, and neither has been buildable since the day it landed.
     Verified by sweeping all 53 species through their own names: exactly
     those two fail.

  2. A placement layer needs to ask for `pebble` a few thousand times per site
     and get a pebble every time. `parse("pebble")` works today -- because no
     other keyword currently beats it. That is a coincidence in a lookup
     table, not a contract. Add a species with an overlapping keyword and a
     level silently gets dressed with something else, with nothing red.

THE CHANGE.

`intent.parse(prompt, species=...)`, `build.build_specimen(..., species=...)`,
`zoo_cli --species`. Naming the species skips keyword matching entirely.

  * An unknown name RAISES and lists the alternatives. A program asking for a
    species that does not exist has a bug; it should surface at the call, not
    as a quietly different asset three stages later.
  * The prompt is still parsed for material, colour, wear, size and era, so a
    caller gets the species it requires with the styling it wants:
    `--species pebble --prompt "wet mossy"`.
  * With no prompt, the species name BECOMES the prompt. Repeated requests for
    one species then hash to one `seeding.root_key`, instead of the asset's
    identity depending on whichever empty string a caller happened to pass.
  * `Intent.species_source` records "keyword" or "explicit" and rides into
    `to_dict()`, so a specimen's provenance says whether a human's words or a
    program's argument chose it.

Deliberately NOT changed: the keyword sets for wallCorner and wallEnd. This
release adds the door. Rewriting matching rules is a separate change with its
own blast radius, and `test_two_species_are_unreachable_by_prompt` pins the
current set both ways -- it fails if the set grows AND if it shrinks, so
whoever fixes the keywords is told to update the test rather than allowed to
drift past it.

VERIFIED BEFORE SHIPPING. New suite `tests/test_species_by_name.py`, 10 tests,
including a round trip over every species in the library. With the original
`intent.py` restored: 9 failed, 1 passed. With the patch: 10 passed, and the
existing `test_intent.py` is untouched and still green (17 together).

    python patch_species_by_name.py --check
    python patch_species_by_name.py --selftest
    python patch_species_by_name.py
    python patch_species_by_name.py --revert
"""
