def repo_root(start=None):
    d = os.path.abspath(start or os.path.dirname(os.path.abspath(__file__)))
    for _ in range(8):
        if (os.path.isdir(os.path.join(d, "zoo", "zoo_keeper"))
                and os.path.isdir(os.path.join(d, "tools"))):
            return d
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    return None


def sha(b):
    return hashlib.sha256(b).hexdigest()


def rd(p):
    with open(p, "rb") as fh:
        return fh.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as fh:
        fh.write(b)


def plan(root):
    rows, ok = [], True
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        exists = os.path.isfile(p)
        if d["kind"] == "new":
            if exists and sha(rd(p)) == d["post_sha"]:
                rows.append((rel, "already-current", True))
            elif exists:
                rows.append((rel, "EXISTS AND DIFFERS - refusing", False))
                ok = False
            else:
                rows.append((rel, f"create {d['post_bytes']} B", True))
            continue
        if not exists:
            rows.append((rel, "MISSING - refusing", False))
            ok = False
            continue
        cur = sha(rd(p))
        if cur == d["post_sha"]:
            rows.append((rel, "already-current", True))
        elif cur == d["pre_sha"]:
            rows.append((rel, f"replace {d['pre_bytes']} -> {d['post_bytes']} B",
                         True))
        else:
            rows.append((rel, f"DRIFT sha {cur[:12]} != {d['pre_sha'][:12]}",
                         False))
            ok = False
    return ok, rows


def show(rows):
    w = max(len(r[0]) for r in rows)
    for rel, msg, good in rows:
        print(f"  {'ok ' if good else 'STOP'}  {rel:<{w}}  {msg}")


def apply(root):
    ok, rows = plan(root)
    show(rows)
    if not ok:
        print("\nREFUSING: nothing written. Resolve the lines marked STOP.")
        return 1
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        if os.path.isfile(p):
            cur = rd(p)
            if sha(cur) == d["post_sha"]:
                continue
            side = p + SIDECAR
            if not os.path.exists(side):
                wr(side, cur)
        wr(p, base64.b64decode(d["b64"]))
        assert sha(rd(p)) == d["post_sha"], rel
        n += 1
    print(f"\nWROTE {n} file(s). Sidecars: *{SIDECAR}")
    print("Next:")
    print("  cd zoo")
    print("  python -m pytest tests -q")
    print("Expect 294 passed (284 + the 10 new ones), 2 skipped.")
    return 0


def revert(root):
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        side = p + SIDECAR
        if os.path.exists(side):
            wr(p, rd(side))
            os.remove(side)
            print(f"  reverted {rel}")
            n += 1
        elif d["kind"] == "new" and os.path.isfile(p):
            if sha(rd(p)) == d["post_sha"]:
                os.remove(p)
                print(f"  removed  {rel} (this patch created it)")
                n += 1
            else:
                print(f"  KEPT     {rel} (modified since; not ours to delete)")
    print(f"reverted {n} file(s)")
    return 0


def selftest():
    bad = 0

    def fail(msg):
        nonlocal bad
        print(f"  FAIL  {msg}")
        bad += 1

    print("patch_species_by_name selftest")

    for rel, d in PAYLOAD.items():
        b = base64.b64decode(d["b64"])
        if sha(b) != d["post_sha"] or len(b) != d["post_bytes"]:
            fail(f"payload {rel} does not match its recorded hash/size")
    print(f"  ok    {len(PAYLOAD)} payloads decode to their recorded hashes")

    import ast

    def src(rel):
        return base64.b64decode(PAYLOAD[rel]["b64"]).decode("utf-8")

    intent_src = src("zoo/zoo_keeper/core/intent.py")
    build_src = src("zoo/zoo_keeper/bpylayer/build.py")
    cli_src = src("zoo/tools/zoo_cli.py")

    # The three call sites must agree on the argument NAME, or the CLI flag
    # reaches build_specimen and build_specimen drops it on the floor with no
    # error -- the exact failure this patch exists to prevent one layer up.
    def has_kwarg(source, func, kw):
        for node in ast.walk(ast.parse(source)):
            if isinstance(node, ast.FunctionDef) and node.name == func:
                names = [a.arg for a in node.args.args
                         + node.args.kwonlyargs]
                return kw in names
        return None

    if has_kwarg(intent_src, "parse", "species") is not True:
        fail("intent.parse does not take a `species` argument")
    if has_kwarg(build_src, "build_specimen", "species") is not True:
        fail("build_specimen does not take a `species` argument")
    if "species=args.species" not in cli_src:
        fail("zoo_cli never forwards --species to build_specimen")
    if 'ap.add_argument("--species"' not in cli_src:
        fail("zoo_cli does not declare --species")
    print("  ok    parse / build_specimen / zoo_cli all speak `species`")

    # The unknown-name path must raise. Exercised for real by exec'ing the
    # parse function's guard in isolation would need the genome folder, so
    # assert on the source instead -- and assert it is a raise, not a return.
    if "raise ValueError(" not in intent_src or \
            "No species named" not in intent_src:
        fail("intent.parse does not raise on an unknown species name")
    print("  ok    an unknown species name raises rather than falls back")

    # FALSIFICATION: the argument must actually bypass keyword matching. If
    # `_find_species` still runs unconditionally, everything above can be true
    # and the feature still does nothing.
    tree = ast.parse(intent_src)
    parse_fn = next(n for n in ast.walk(tree)
                    if isinstance(n, ast.FunctionDef) and n.name == "parse")
    calls = [n for n in ast.walk(parse_fn)
             if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
             and n.func.id == "_find_species"]
    guarded = any(isinstance(anc, ast.If)
                  for anc in ast.walk(parse_fn)
                  for sub in ast.walk(anc)
                  if sub in calls)
    if not calls:
        fail("_find_species is no longer called at all — keyword matching is gone")
    elif not guarded:
        fail("_find_species is called unconditionally — `species` cannot win")
    else:
        print("  ok    keyword matching is skipped when a species is named")

    tests_src = src("zoo/tests/test_species_by_name.py")
    for needle in ("wallCorner", "wallEnd", "species_source",
                   "list_species()"):
        if needle not in tests_src:
            fail(f"the new test file never mentions {needle}")
    print("  ok    the new suite covers the two unreachable species by name")

    ver = src("zoo/VERSION").strip()
    if ver != "Zoo 0.38.0":
        fail(f"VERSION payload is {ver!r}")
    ch = src("zoo/CHANGELOG.md")
    for tag in ("## [0.38.0]", "## [0.37.0]", "## [0.36.0]"):
        if tag not in ch:
            fail(f"CHANGELOG payload is missing {tag}")
    print("  ok    VERSION 0.38.0 and a CHANGELOG that keeps its history")

    ref = base64.b64decode(next(iter(PAYLOAD.values()))["b64"])
    mut = bytearray(ref)
    mut[len(mut) // 2] ^= 0x20
    if sha(bytes(mut)) == sha(ref):
        fail("a mutated payload hashed identically")
    else:
        print("  ok    one flipped byte changes the hash")

    print("SELFTEST", "PASSED" if bad == 0 else f"FAILED ({bad})")
    return 1 if bad else 0


def main(argv):
    if "--selftest" in argv:
        return selftest()
    root = None
    if "--root" in argv:
        root = os.path.abspath(argv[argv.index("--root") + 1])
    root = root or repo_root()
    if not root:
        print("Could not find the gabagool_factory root. Pass --root <path>.")
        return 2
    print(f"repo root: {root}")
    if "--revert" in argv:
        return revert(root)
    ok, rows = plan(root)
    if "--check" in argv:
        show(rows)
        print("\n--check only: nothing written."
              + ("" if ok else "  RESOLVE THE STOP LINES FIRST."))
        return 0 if ok else 1
    return apply(root)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
